const body = $json.body;
if (!body.txHash || !body.rawAmountWei || body.tokenDecimals === undefined) {
  throw new Error('Malformed payment event');
}
const raw = BigInt(body.rawAmountWei);
const decimals = Number(body.tokenDecimals);
const divisor = BigInt(10) ** BigInt(decimals);
const integerPart = raw / divisor;
const remainder = raw % divisor;
const remainderStr = remainder.toString().padStart(decimals, '0');
const tokenUnitsStr = decimals > 0 ? `${integerPart}.${remainderStr}` : integerPart.toString();
return [{
  json: {
    chainId: body.chainId || 31337,
    txHash: body.txHash.toLowerCase(),
    logIndex: body.logIndex || 0,
    blockNumber: body.blockNumber || 1,
    blockTimestamp: new Date().toISOString(),
    senderAddress: body.senderAddress.toLowerCase(),
    recipientAddress: body.recipientAddress.toLowerCase(),
    tokenAddress: body.tokenAddress.toLowerCase(),
    tokenSymbol: body.tokenSymbol || 'USDC',
    tokenDecimals: decimals,
    rawAmount: body.rawAmountWei,
    tokenUnits: parseFloat(tokenUnitsStr),
    customerId: body.customerId || 'CUST_DIRECT',
    invoiceId: body.invoiceId || 'INV-2026-001',
    expectedUsd: body.expectedUsd || 100.00
  }
}];

const prev = $('Normalize Token Decimals').item.json;
let price = 1.0;
if ($json && $json.price) {
  price = parseFloat($json.price);
} else if (prev.tokenSymbol === 'ETH' || prev.tokenSymbol === 'WETH') {
  price = 3000.00;
}
const fiatAmount = (prev.tokenUnits * price).toFixed(2);
let status = 'CONFIRMED';
const diff = parseFloat(fiatAmount) - prev.expectedUsd;
if (Math.abs(diff) <= 0.01) status = 'RECONCILED';
else if (diff < 0) status = 'UNDERPAID';
else status = 'OVERPAID';
return [{
  json: {
    ...prev,
    fiatRateUsd: price.toFixed(6),
    fiatAmountUsd: fiatAmount,
    reconciliationStatus: status
  }
}];
